package com.example.mail;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

@Service
public class MailService {
    @Value("${mail.host}")
    private String host;

    @Value("${mail.port:587}")
    private int port;

    @Value("${mail.from}")
    private String from;

    public void send(String to, String subject, String body) {
        SmtpClient.connect(host, port).send(from, to, subject, body);
    }
}

package com.example.mail;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
public class DigestJob {
    @Value("${mail.host}")
    private String host;

    @Value("${mail.port:25}")
    private int port;

    @Value("${mail.from}")
    private String from;

    @Scheduled(cron = "0 0 8 * * *")
    public void run() {
        SmtpClient client = SmtpClient.connect(host, port);
        DigestQueue.drain().forEach(digest -> client.send(from, digest.to(), "Daily digest", digest.body()));
    }
}

