package com.example.mail;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.boot.context.properties.bind.DefaultValue;

@ConfigurationProperties(prefix = "mail")
public record MailProperties(String host, @DefaultValue("587") int port, String from) {
}

@Service
public class MailService {
    private final MailProperties mail;

    public MailService(MailProperties mail) {
        this.mail = mail;
    }

    public void send(String to, String subject, String body) {
        SmtpClient.connect(mail.host(), mail.port()).send(mail.from(), to, subject, body);
    }
}

import jakarta.validation.constraints.NotBlank;
import org.springframework.validation.annotation.Validated;

@Validated
@ConfigurationProperties(prefix = "mail")
public record MailProperties(@NotBlank String host, @DefaultValue("587") int port, @NotBlank String from) {
}
